/**
 * LoneScale Node - Version 1
 * Discriminator: resource=contact, operation=enrich
 */


interface Credentials {
  loneScaleApi: CredentialReference;
}

/** Enrich or source contacts */
export type LoneScaleV1ContactEnrichParams = {
  resource: 'contact';
  operation: 'enrich';
/**
 * Types of enrichment to perform
 * @default ["email"]
 */
    enrichmentType?: Array<'email' | 'phone' | 'profile'>;
/**
 * Contact first name
 */
    firstName: string | Expression<string>;
/**
 * Contact last name
 */
    lastName: string | Expression<string>;
/**
 * Contact company name, improves matching accuracy
 */
    enrichCompanyName?: string | Expression<string>;
/**
 * Contact company domain, improves matching accuracy
 */
    enrichCompanyDomain?: string | Expression<string>;
/**
 * Whether to flag if the contact changed company since the input data. Only effective when Enrichment Type includes Profile.
 * @default false
 */
    detectJobChange?: boolean | Expression<boolean>;
/**
 * Additional Fields
 * @default {}
 */
    enrichAdditionalFields?: {
    /** Known contact email to improve matching
     */
    email?: string | Expression<string>;
    /** Your CRM record ID, echoed back in the response
     */
    contactId?: string | Expression<string>;
    /** Contact job title
     */
    jobTitle?: string | Expression<string>;
    /** Contact Linkedin URL
     */
    linkedinUrl?: string | Expression<string>;
  };
};

export type LoneScaleV1ContactEnrichNode = {
  type: 'n8n-nodes-base.loneScale';
  version: 1;
  config: NodeConfig<LoneScaleV1ContactEnrichParams> & { credentials?: Credentials };
};